package com.example.suiri;
import android.app.*;
import android.content.*;
import android.widget.*;
import android.text.util.Linkify;
import org.json.*;
import java.time.*;

public final class WeatherUi {
 public static void strip(MainActivity a,LinearLayout into){LinearLayout box=a.column();box.setPadding(a.dp(15),a.dp(10),a.dp(15),a.dp(10));box.setBackground(Saber.shape(a,Saber.SURFACE,22,Saber.LINE));TextView title=a.text(Weather.summary(a),20);title.setTypeface(null,android.graphics.Typeface.BOLD);LinearLayout heading=new LinearLayout(a);ImageView avatar=Saber.picture(a,0,true);avatar.setOnClickListener(v->a.startActivity(new Intent(a,PetChatActivity.class).putExtra("weather",true)));heading.addView(avatar,new LinearLayout.LayoutParams(a.dp(48),a.dp(48)));heading.addView(title,new LinearLayout.LayoutParams(0,-2,1));box.addView(heading);TextView line=a.text(Weather.advice(a),13);line.setTextColor(Saber.GOLD);box.addView(line);box.setOnClickListener(v->details(a));into.addView(box,new LinearLayout.LayoutParams(-1,-2));}
 public static void details(MainActivity a){LinearLayout content=a.column();content.setPadding(a.dp(18),0,a.dp(18),0);content.addView(a.text(Weather.advice(a),18));content.addView(a.button("更新位置",()->{a.prefs.edit().putBoolean("weatherLocation",true).apply();a.weatherLocation.start(true);}));content.addView(a.text(Weather.summary(a)+"\n"+Weather.stamp(a),16));String error=a.prefs.getString("weatherError","");if(!error.isEmpty())content.addView(a.text(error,13));for(String kind:new String[]{"daily","alert"}){long time=a.prefs.getLong("weather.time."+kind,0);content.addView(a.text((kind.equals("daily")?"预报":"预警")+"："+(time==0?"尚未获取":Instant.ofEpochMilli(time).atZone(Schedule.ZONE).toLocalDateTime().toString().replace('T',' '))+" 获取",12));}JSONObject day=WeatherRules.today(Weather.data(a,"daily"),LocalDate.now(Schedule.ZONE));if(day.length()>0)content.addView(a.text("今日预报："+WeatherRules.obj(WeatherRules.obj(day,"daytime"),"condition").optString("text")+" / 夜间 "+WeatherRules.obj(WeatherRules.obj(day,"nighttime"),"condition").optString("text"),15));JSONArray alerts=WeatherRules.active(Weather.data(a,"alert"),Instant.now());if(alerts.length()==0)content.addView(a.text(a.prefs.getLong("weather.time.alert",0)==0?"预警尚未获取，不能判断有无预警":"最近获取的数据中没有有效预警；请留意数据时间",14));for(int i=0;i<alerts.length();i++){JSONObject v=alerts.optJSONObject(i);content.addView(a.text(v.optString("headline")+"\n"+v.optString("senderName")+" · "+v.optString("issuedTime")+"\n"+v.optString("description")+"\n"+v.optString("instruction"),15));}StringBuilder sources=new StringBuilder("数据来源：和风天气\nhttps://www.qweather.com/\n");java.util.Set<String> shown=new java.util.LinkedHashSet<>();for(String k:new String[]{"current","daily","alert"}){JSONArray refs=WeatherRules.obj(Weather.data(a,k),"metadata").optJSONArray("attributions");if(refs!=null)for(int i=0;i<refs.length();i++)shown.add(refs.optString(i));}for(String s:shown)sources.append(s).append('\n');TextView refs=a.text(sources.toString(),11);Linkify.addLinks(refs,Linkify.WEB_URLS);content.addView(refs);ScrollView scroll=new ScrollView(a);scroll.addView(content);new UiDialog.Builder(a).setTitle("Saber · 天气").setView(scroll).setPositiveButton("关闭",null).setNeutralButton("配置",(d,w)->settings(a)).setNegativeButton("检查更新",(d,w)->{Weather.ensure(a);a.toast("已检查：实况/预警每小时、预报每6小时，两地显示时实况每2小时，缓存未过期不重复请求");}).show();}
 public static void settings(MainActivity a){LinearLayout form=a.column();form.setPadding(a.dp(18),a.dp(8),a.dp(18),a.dp(8));form.addView(a.button("定位当前位置",()->{a.prefs.edit().putBoolean("weatherLocation",true).apply();a.weatherLocation.start(true);}));CheckBox locate=new CheckBox(a);locate.setText("跟随当前位置");locate.setChecked(a.prefs.getBoolean("weatherLocation",true));form.addView(locate);EditText host=a.field(form,"API Host（账号专属）",a.prefs.getString("weatherHost",""));EditText key=a.field(form,"API Key（已保存："+Secrets.has(a,"weather")+"）","");key.setInputType(129);EditText name=a.field(form,"地点名称",Weather.city(a));EditText lat=a.field(form,"纬度（上海市区示例31.23）",a.prefs.getString("weatherLat","31.23"));EditText lon=a.field(form,"经度（上海市区示例121.47）",a.prefs.getString("weatherLon","121.47"));CheckBox enabled=new CheckBox(a);enabled.setText("启用天气自动更新");enabled.setChecked(a.prefs.getBoolean("weatherEnabled",true));form.addView(enabled);CheckBox notify=new CheckBox(a);notify.setText("Saber 天气通知（也需系统通知权限）");notify.setChecked(a.prefs.getBoolean("weatherNotify",true));form.addView(notify);String month=YearMonth.now(Schedule.ZONE).toString();int used=month.equals(a.prefs.getString("weatherMonth",""))?a.prefs.getInt("weatherCount",0):0;form.addView(a.button("用量与说明",()->new UiDialog.Builder(a).setTitle("天气用量").setMessage("本月请求 "+used+" / 3000。实况与预警每小时、预报每6小时更新；实际额度与计费以账户规则为准。").setPositiveButton("关闭",null).show()));form.addView(a.button("打开和风开发者官网",()->a.launch(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://dev.qweather.com/")))));ScrollView scroll=new ScrollView(a);scroll.addView(form);AlertDialog d=new UiDialog.Builder(a).setTitle("和风天气设置").setView(scroll).setPositiveButton("保存",null).setNegativeButton("取消",null).setNeutralButton("移除天气凭据",(x,w)->{try{Secrets.set(a,"weather","");a.prefs.edit().putBoolean("weatherEnabled",false).putLong("weatherRevision",System.currentTimeMillis()).apply();Weather.ensure(a);SuiRiWidget.refresh(a);a.render();}catch(Exception e){a.toast("移除失败");}}).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{try{String h=WeatherRules.host(host.getText().toString()),la=WeatherRules.coordinate(lat.getText().toString(),true),lo=WeatherRules.coordinate(lon.getText().toString(),false),n=name.getText().toString().trim(),k=key.getText().toString().trim();if(n.isEmpty()||n.length()>40)throw new Exception("地点名称需1–40字");if(!k.isEmpty()){if(!k.matches("[A-Za-z0-9._-]{8,4096}"))throw new Exception("API Key格式异常");Secrets.set(a,"weather",k);}boolean changed=!h.equals(a.prefs.getString("weatherHost",""))||!la.equals(a.prefs.getString("weatherLat",""))||!lo.equals(a.prefs.getString("weatherLon",""))||!k.isEmpty();android.content.SharedPreferences.Editor edit=a.prefs.edit().putBoolean("weatherLocation",locate.isChecked()).putString("weatherHost",h).putString("weatherLat",la).putString("weatherLon",lo).putString("weatherCity",n).putBoolean("weatherEnabled",enabled.isChecked()).putBoolean("weatherNotify",notify.isChecked()).putLong("weatherRevision",System.currentTimeMillis());if(changed)for(String kind:Weather.KINDS){edit.remove("weather."+kind).remove("weather.time."+kind).remove("weather.attempt."+kind).remove("weather.shanghai."+kind).remove("weather.time.shanghai."+kind).remove("weather.attempt.shanghai."+kind);}if(!locate.isChecked())edit.putBoolean("weatherLocated",false).putString("weatherRegion","");edit.commit();a.weatherLocation.start(locate.isChecked());Weather.ensure(a);SuiRiWidget.refresh(a);d.dismiss();a.render();if(notify.isChecked()&&!Reminders.notifications(a))a.notificationPermission();}catch(Exception e){a.toast(e.getMessage());}}));d.show();}
}
